"""Batch 51 (Nov 9, 2026): long-sentence (>18 words) rewrites applied to the BUILDERS, not the built HTML, so a rebuild
reproduces the final pages. Idempotent: a pair whose old text is already gone is skipped only if the new text is present.
Run: python3 patches/fix_batch51_long.py   (then rebuild the seven pages)"""
import os, sys
B = '/home/claude/tools/builders_city/'

def fix(fn, pairs):
    p = B + fn
    s = open(p, encoding='utf-8').read()
    n = 0
    for a, b in pairs:
        c = s.count(a)
        if c == 0:
            assert b in s, ('missing', fn, a[:70])
            continue
        s = s.replace(a, b); n += c
    open(p, 'w', encoding='utf-8').write(s)
    print(fn, 'replacements:', n)

